{
  "understanding": {
    "purpose": "தமிழ்நாட்டுக் கோயில்களின் இடம், திறக்கும் நேரம் மற்றும் தனிச்சிறப்புகளை ஒரே பார்வையில் அறிய உதவும் அட்டவணை.",
    "reading": "வாசகர் முதலில் கோயிலை அல்லது நகரத்தைக் கண்டுபிடித்து, அதே வரியில் நேரத்தையும் சிறப்பையும் படிப்பார்; பயணத் திட்டமிடும்போது நேரங்களையும் ஒப்பிடலாம்.",
    "groups": [
      "கோயில் மற்றும் நகரம் சேர்ந்து இடத்தை அடையாளப்படுத்துகின்றன.",
      "திறக்கும் நேரம் மற்றும் சிறப்பு ஒவ்வொரு கோயிலையும் பற்றிய வேறுபட்ட தகவல்களை வழங்குகின்றன; நேரம் ஒப்பிடக்கூடிய மதிப்பு, சிறப்பு விரிவான விளக்கம்."
    ],
    "keep_intact": [
      "கோயில் மற்றும் நகரப் பெயர்களில் உள்ள தனிச்சொற்கள்",
      "திறக்கும் நேரத்தில் ஒவ்வொரு நேர வரம்பும்",
      "சிறப்பு விளக்கத்தில் உள்ள நீளமான தமிழ்ச் சொற்கள்"
    ],
    "may_wrap": [
      "பல சொற்களைக் கொண்ட கோயில் பெயர்கள் சொற்களுக்கு இடையில் மடங்கலாம்.",
      "காலை மற்றும் மாலை நேர வரம்புகள் தனித்தனி வரிகளில் அமையலாம்.",
      "சிறப்பு விளக்கங்கள் இயல்பாகப் பல வரிகளில் மடங்கலாம்; அவற்றால் உயரமாகும் வரிகளில் பெயர் அல்லது நேரத்தின் மடிப்பையும் இடமளிக்கலாம்."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [186, 118, 196, 219],
      "idea": "கோயில் பெயர், நகரம் மற்றும் முழு நேரத்தை ஒரே வரியில் வைத்து, சிறப்பு விளக்கத்திலேயே பெரும்பாலான மடிப்புகளை ஏற்கிறது."
    },
    {
      "name": "B",
      "widths": [135, 118, 120, 346],
      "idea": "சிறப்பு விளக்கங்களுக்கு அதிக இடம் வழங்கி, கோயில் பெயர்களும் காலை மற்றும் மாலை நேரங்களும் தேவைக்கேற்ப மடங்க அனுமதிக்கிறது."
    },
    {
      "name": "C",
      "widths": [155, 118, 160, 286],
      "idea": "அடையாளம், நேரம் மற்றும் விளக்கத்துக்கு இடத்தைச் சமநிலையுடன் பகிர்ந்து, மடிப்புகளைப் பல நெடுவரிசைகளில் விநியோகிக்கிறது."
    }
  ]
